result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "read_cal.py", "content": "#!/usr/bin/env python3
"""Minimal validating reader for calendars produced by make_cal.py.

Parses the ICS back into dictionaries using its own tiny parser:
each VEVENT becomes::

    {"uid": ..., "summary": ..., "dtstart": datetime.date, ...raw props}

Handles CRLF/LF line endings and unfolds continuation lines (RFC 5545
folding) even though make_cal.py never folds, so the reader tolerates
folded input too. Validates structural basics: BEGIN/END pairing,
presence of UID / DTSTART / SUMMARY per event, and absence of bare LF.
"""

from __future__ import annotations

import argparse
import datetime as dt
import sys
from typing import Any


class CalendarError(ValueError):
    """Raised when the ICS payload is malformed."""


def _unfold(data: bytes) -> str:
    if b"\n" in data.replace(b"\r\n", b""):
        raise CalendarError("bare LF found; ICS requires CRLF line endings")
    text = data.decode("utf-8").replace("\r\n", "\n")
    # Unfold RFC 5545 continuations (line starting with space or tab).
    out: list[str] = []
    for line in text.split("\n"):
        if line[:1] in (" ", "\t") and out:
            out[-1] += line[1:]
        else:
            out.append(line)
    return "\n".join(out)


def _parse_prop(line: str) -> tuple[str, dict[str, str], str]:
    """Split 'NAME;PARAM=v;PARAM2=v2:value' -> (name, params, value)."""
    if ":" not in line:
        raise CalendarError(f"property without ':' separator: {line!r}")
    head, _, value = line.partition(":")
    parts = head.split(";")
    name = parts[0].upper()
    params: dict[str, str] = {}
    for part in parts[1:]:
        k, sep, v = part.partition("=")
        if not sep:
            raise CalendarError(f"malformed parameter {part!r} in {line!r}")
        params[k.upper()] = v
    return name, params, value


def _parse_date(value: str) -> dt.date:
    try:
        return dt.datetime.strptime(value, "%Y%m%d").date()
    except ValueError as exc:
        raise CalendarError(f"bad DATE value {value!r}") from exc


def parse_calendar(data: bytes) -> list[dict[str, Any]]:
    """Parse ICS bytes into a list of event dicts."""
    events: list[dict[str, Any]] = []
    stack: list[str] = []
    current: dict[str, Any] | None = None

    for lineno, line in enumerate(_unfold(data).split("\n"), start=1):
        if not line.strip():
            continue
        name, params, value = _parse_prop(line)

        if name == "BEGIN":
            stack.append(value.upper())
            if value.upper() == "VEVENT":
                current = {"params": {}}
            continue
        if name == "END":
            block = value.upper()
            if not stack or stack[-1] != block:
                raise CalendarError(f"line {lineno}: unbalanced END:{block}")
            stack.pop()
            if block == "VEVENT":
                assert current is not None
                missing = {"UID", "DTSTART", "SUMMARY"} - current.keys()
                if missing:
                    raise CalendarError(
                        f"VEVENT missing properties: {sorted(missing)}"
                    )
                events.append(current)
                current = None
            continue

        if current is None:
            if name not in ("VERSION", "PRODID", "CALSCALE"):
                raise CalendarError(
                    f"line {lineno}: property outside any component: {name}"
                )
            continue

        if name == "DTSTART":
            if params.get("VALUE") != "DATE":
                raise CalendarError("DTSTART must use VALUE=DATE (all-day)")
            current["dtstart"] = _parse_date(value)
        elif name in ("UID", "SUMMARY"):
            current[name.lower()] = value
        else:
            current.setdefault("extra", []).append((name, params, value))

    if stack:
        raise CalendarError(f"unclosed component(s): {stack}")
    return events


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description="Validate and read an ICS file")
    p.add_argument("path", nargs="?", default="calendar.ics")
    args = p.parse_args(argv)

    try:
        with open(args.path, "rb") as fh:
            events = parse_calendar(fh.read())
    except (OSError, CalendarError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    for ev in events:
        print(f"{ev['uid']}  {ev['dtstart'].isoformat()}  {ev['summary']}")
    print(f"{len(events)} event(s), OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"})
